function [ang] = qangle(a, b)
%QANGLE  The angle between two attitudes: 2 acos(min(1, |a . b|)).
%   a: real[1][4] (passed a plain number)
%   b: real[1][4] (passed a plain number)
%   returns ang: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    ang = 0;
    d = asils.pc.fabs(((((a(1) * b(1)) + (a(2) * b(2))) + (a(3) * b(3))) + (a(4) * b(4))));
    ang = (2 * acos(asils.pc.choose((d > 1), 1, d)));
end
